const { chromium } = require('<local>/project/y86/node_modules/playwright')
const token = process.argv[2]
;(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] })
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
  page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE-ERR', m.text().slice(0, 200)) })
  await page.goto(`http://127.0.0.1:3094/?token=${token}`, { waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.waitForTimeout(3000)
  const ensure = await page.evaluate(async () => {
    const r = await fetch('/api/super-agent/ui/ensure', { method: 'POST', headers: { 'content-type': 'application/json' }, credentials: 'same-origin', body: '{}' })
    return { http: r.status, body: await r.json().catch(() => null) }
  })
  console.log('ENSURE', JSON.stringify(ensure).slice(0, 2000))
  await page.waitForTimeout(3000)
  const state = await page.evaluate(async () => (await fetch('/api/super-agent/ui/state', { credentials: 'same-origin' })).json())
  console.log('STATE', JSON.stringify({ ok: state.ok, active: state.active, router: state.router && { sessionId: state.router.sessionId, projectRoot: state.router.projectRoot, status: state.router.status && { tasks: state.router.status.counts && state.router.status.counts.tasks } } }).slice(0, 3000))
  const models = await page.evaluate(async () => (await fetch('/api/super-agent/ui/models', { credentials: 'same-origin' })).json())
  console.log('MODELS', JSON.stringify(models).slice(0, 5000))
  await browser.close()
})().catch((e) => { console.error(e); process.exit(1) })

embedded.probeSpaced:
const { chromium } = require('<local>/project/y86/node_modules/playwright')
const token = process.argv[2]
const work = process.argv[3]
const probe = process.argv[4]
const spacingMs = Number(process.argv[5] || 1000)
const n = Number(process.argv[6] || 3)
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
const onePrompt = (i) => `Use superagent_dispatch exactly once now, with no other tool and no waiting. ` +
  `Parameters: title="P1C ${probe} W${i}", brief="Reply with exactly P1C-OK-${probe}-${i} and stop. Do not use any tool.", cwd="${work}". ` +
  `Do NOT call superagent_close. Reply with the task id only.`
;(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] })
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
  await page.goto(`http://127.0.0.1:3094/?token=${token}`, { waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.waitForTimeout(1500)
  const state = () => page.evaluate(async () => (await fetch('/api/super-agent/ui/state', { credentials: 'same-origin' })).json())
  const activity = () => page.evaluate(async () => (await fetch('/api/super-agent/ui/activity?limit=100', { credentials: 'same-origin' })).json())
  const detail = (id) => page.evaluate(async (id) => (await fetch(`/api/super-agent/ui/task?task_id=${encodeURIComponent(id)}`, { credentials: 'same-origin' })).json(), id)
  // Wait for the Router to be idle and no pending triggers, so spacing starts from a calm baseline.
  for (let i = 0; i < 60; i += 1) {
    const s = await state()
    const st = s?.router?.status
    if (st?.router?.status === 'idle' && (st?.counts?.pending ?? 0) === 0) break
    await sleep(1000)
  }
  const sent = []
  for (let i = 1; i <= n; i += 1) {
    const at = Date.now()
    const ing = await page.evaluate(async ({ text, probe, i }) => {
      const r = await fetch('/api/super-agent/ingest', {
        method: 'POST', headers: { 'content-type': 'application/json' }, credentials: 'same-origin',
        body: JSON.stringify({ source: 'im', threadKey: `p1c:${probe}:${i}`, externalId: `p1c-${probe}-${i}-${Date.now()}`, actor: 'tester', direct: true, mentions: ['super-agent'], text }),
      })
      return { http: r.status, body: await r.json().catch(() => null) }
    }, { text: onePrompt(i), probe, i })
    sent.push({ i, at, ing })
    if (i < n) await sleep(spacingMs)
  }
  const t0 = Date.now()
  let lastSig = ''
  let tasks = []
  for (let i = 0; i < 180; i += 1) {
    await sleep(500)
    const a = await activity()
    tasks = (a?.activity ?? []).filter((t) => String(t.title ?? '').includes(`P1C ${probe}`))
    const sig = tasks.map((t) => `${t.title}:${t.status}`).join('|')
    if (sig !== lastSig) {
      console.log(`+${((Date.now() - t0) / 1000).toFixed(1)}s`, sig || '(none yet)')
      lastSig = sig
    }
    if (tasks.length >= n && tasks.every((t) => !['starting', 'queued'].includes(t.status))) break
  }
  await sleep(12000) // late-lost观察窗（1s watchdog + 10s grace 也足够触发）
  const a = await activity()
  tasks = (a?.activity ?? []).filter((t) => String(t.title ?? '').includes(`P1C ${probe}`))
  const details = []
  for (const t of tasks) details.push(await detail(t.id))
  const lost = tasks.filter((t) => t.status === 'lost').length
  console.log('SUMMARY', JSON.stringify({
    probe, spacingMs, n,
    sent: sent.map((s) => ({ i: s.i, http: s.ing.http, ok: s.ing.body?.ok, at: s.at })),
    tasks: tasks.map((t) => ({ id: t.id, title: t.title, status: t.status, workerSessionId: t.workerSessionId, createdAt: t.createdAt, updatedAt: t.updatedAt, lostReason: t.lostReason })),
    lost, total: tasks.length,
    details: details.map((d) => ({ id: d?.task?.id, status: d?.task?.status, lostReason: d?.task?.lostReason, lastReport: d?.task?.lastReport?.reason })),
  }, null, 1))
  await browser.close()
  process.exit(lost === 0 && tasks.length >= n ? 0 : 3)
})().catch((e) => { console.error(e); process.exit(1) })
